     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	import org.springframework.samples.petclinic.rest.escalation.DailyRegistrationLimitException;
     7	
     8	/**
     9	 * Rejects a create-owner request once the maximum number of owners ({@value #DAILY_LIMIT})
    10	 * have already been registered on the new owner's (adjusted, business-day)
    11	 * {@link Owner#getRegistrationDate() registrationDate}, responding 429 via
    12	 * {@link DailyRegistrationLimitException}. Runs after the registration date has been
    13	 * resolved so the count buckets by the same business day the new owner would be stored under.
    14	 */
    15	public class RequireDailyRegistrationCapacity {
    16	
    17	    /** Maximum owners that may be registered on a single business day; the request is rejected once reached. */
    18	    static final int DAILY_LIMIT = 100;
    19	
    20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DailyRegistrationLimitException {
    21	        long registeredThatDay = OwnerRegistrations.countOn(ownerRepository, owner.getRegistrationDate());
    22	        if (registeredThatDay >= DAILY_LIMIT) {
    23	            throw new DailyRegistrationLimitException(DAILY_LIMIT);
    24	        }
    25	    }
    26	}

