package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.ResultActions;

import tools.jackson.databind.node.ObjectNode;

/**
 * Every rejection (400, 409, 429) must be an RFC7807 {@code application/problem+json}
 * body carrying {@code type}, {@code title}, {@code status} and {@code detail}, with the
 * {@code status} member equal to the HTTP status. One test per status class, each driving
 * a real rejecting rule on {@code POST /api/owners}.
 */
class RejectionsAreProblemJsonTest extends AcceptanceBase {

	/** Assert the shared RFC7807 contract: content type, the four required members and a
	 *  {@code status} member equal to the HTTP status. */
	private void assertProblemJson(ResultActions result, int expectedStatus) throws Exception {
		result.andExpect(content().contentTypeCompatibleWith("application/problem+json"))
				.andExpect(jsonPath("$.type").exists())
				.andExpect(jsonPath("$.title").exists())
				.andExpect(jsonPath("$.status").value(expectedStatus))
				.andExpect(jsonPath("$.detail").exists());
	}

	@Test
	void validationRejectionIsProblemJson() throws Exception {
		ObjectNode o = structuredOwner();
		o.remove("city");
		assertProblemJson(createOwner(o).andExpect(status().isBadRequest()), 400);
	}

	@Test
	void duplicateIdentityRejectionIsProblemJson() throws Exception {
		ObjectNode o = structuredOwner();
		createOwnerOk(o);
		// Exact resubmission collides on the derived identity key -> 409.
		assertProblemJson(createOwner(o).andExpect(status().isConflict()), 409);
	}

	@Test
	void cityAtCapacityRejectionIsProblemJson() throws Exception {
		String city = uniqueCity();
		fillCity(city, 50);
		ObjectNode o = ownerNode();
		o.put("city", city);
		assertProblemJson(createOwner(o).andExpect(status().isConflict()), 409);
	}

	@Test
	void dailyRegistrationLimitRejectionIsProblemJson() throws Exception {
		createMany(100);
		assertProblemJson(createOwner(ownerNode())
				.andExpect(status().isTooManyRequests()), 429);
	}
}

